def is_palindrome(s):
    chars = [c.lower() for c in s if c.isalnum()]
    return chars == chars[::-1]

def chunk(lst, n):
    if n <= 0:
        return []
    return [lst[i:i + n] for i in range(0, len(lst), n)]

def roman(n):
    values = [
        (1000, "M"), (900, "CM"), (500, "D"), (400, "CD"),
        (100, "C"), (90, "XC"), (50, "L"), (40, "XL"),
        (10, "X"), (9, "IX"), (5, "V"), (4, "IV"), (1, "I")
    ]
    result = []
    for value, symbol in values:
        while n >= value:
            result.append(symbol)
            n -= value
    return "".join(result)

def merge_intervals(iv):
    if not iv:
        return []

    intervals = sorted(iv, key=lambda x: x[0])
    merged = [list(intervals[0])]

    for start, end in intervals[1:]:
        if start <= merged[-1][1]:
            merged[-1][1] = max(merged[-1][1], end)
        else:
            merged.append([start, end])

    return merged

def flatten(x):
    result = []
    for item in x:
        if isinstance(item, list):
            result.extend(flatten(item))
        else:
            result.append(item)
    return result

def parse_duration(s):
    units = {'d': 86400, 'h': 3600, 'm': 60, 's': 1}
    total = 0
    num = ''
    seen = False

    for ch in str(s).strip().lower():
        if ch.isdigit():
            num += ch
        elif ch in units:
            if not num:
                raise ValueError("Invalid duration")
            total += int(num) * units[ch]
            num = ''
            seen = True
        else:
            raise ValueError("Invalid duration")

    if not seen or num:
        raise ValueError("Invalid duration")

    return total

def top_k(lst, k):
    if k <= 0:
        return []
    return sorted(lst, reverse=True)[:k]

def is_valid_brackets(s):
    stack = []
    matching = {
        ")": "(",
        "]": "[",
        "}": "{"
    }
    openers = set(matching.values())

    for char in s:
        if char in openers:
            stack.append(char)
        elif char in matching:
            if not stack or stack.pop() != matching[char]:
                return False

    return not stack

def diff_lines(a, b):
    result = []
    for i in range(max(len(a), len(b))):
        if i < len(a) and i < len(b):
            if a[i] == b[i]:
                result.append((' ', a[i]))
            else:
                result.append(('-', a[i]))
                result.append(('+', b[i]))
        elif i < len(a):
            result.append(('-', a[i]))
        else:
            result.append(('+', b[i]))
    return result

